/**
 * MOTORA TypeScript client.
 *
 * Every struct and instruction name here comes from the IDL generated by
 * `anchor build` (idl/motora.json). PDA derivation matches the Rust seeds
 * exactly. No hand-written account layout is used.
 */
import {
  AnchorProvider,
  BN,
  Idl,
  Program,
  type Provider,
  type Wallet,
} from "@coral-xyz/anchor";
import { PublicKey, SystemProgram, type Connection } from "@solana/web3.js";
import IDL_JSON from "./idl/motora.json";

export const IDL = IDL_JSON as Idl;
export type Motora = Idl;
export { BN, PublicKey };

export const PROGRAMS = {
  protocol: "protocol",
  motorcycle: "motorcycle",
  workshop: "workshop",
  service: "service",
  warranty: "warranty",
} as const;

const enc = (s: string) => Buffer.from(s, "utf8");
const leU64 = (n: number | BN) =>
  BN.isBN(n) ? n.toArrayLike(Buffer, "le", 8) : new BN(n).toArrayLike(Buffer, "le", 8);

/** Accept either a PublicKey or its base58 string (handy for React state). */
export const asPublicKey = (value: PublicKey | string): PublicKey =>
  value instanceof PublicKey ? value : new PublicKey(value);

/** Derive all PDAs with the same seeds used by the on-chain program. */
export function derivePdas(programId: PublicKey, identifierHash: Uint8Array) {
  const [protocol] = PublicKey.findProgramAddressSync([enc("protocol")], programId);
  const [motorcycle] = PublicKey.findProgramAddressSync(
    [enc("motorcycle"), Buffer.from(identifierHash)],
    programId,
  );
  return { protocol, motorcycle };
}

export function deriveMotorcyclePda(programId: PublicKey, identifierHash: Uint8Array) {
  return PublicKey.findProgramAddressSync(
    [enc("motorcycle"), Buffer.from(identifierHash)],
    programId,
  );
}

export function deriveWorkshopPda(programId: PublicKey, authority: PublicKey) {
  return PublicKey.findProgramAddressSync(
    [enc("workshop"), authority.toBuffer()],
    programId,
  );
}

export function deriveServicePda(programId: PublicKey, motorcycle: PublicKey, recordId: number) {
  return PublicKey.findProgramAddressSync(
    [enc("service"), motorcycle.toBuffer(), leU64(recordId)],
    programId,
  );
}

export function deriveClaimPda(programId: PublicKey, serviceRecord: PublicKey, claimId: number) {
  return PublicKey.findProgramAddressSync(
    [enc("warranty"), serviceRecord.toBuffer(), leU64(claimId)],
    programId,
  );
}

/** Async, browser-safe VIN hashing. Uses Web Crypto in both browser and Node 22+. */
export async function hashVin(vin: string, salt: string): Promise<Uint8Array> {
  const normalized = `${vin.trim().toUpperCase()}|${salt}`;
  const data = new TextEncoder().encode(normalized);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", data as BufferSource);
  return new Uint8Array(digest);
}

const ERROR_MESSAGES: Record<string, string> = {
  UnauthorizedWorkshop: "La wallet firmante no es la autoridad de este taller.",
  NotMotorcycleOwner: "Solo el propietario de la motocicleta puede realizar esta acción.",
  WorkshopInactive: "El taller está desactivado.",
  MotorcycleInactive: "La motocicleta está archivada.",
  InvalidMileage: "El kilometraje debe ser válido y nunca menor al actual.",
  InvalidYear: "El año de fabricación no es válido.",
  EmptyField: "Los campos de texto no pueden estar vacíos.",
  ServiceFinalized: "El mantenimiento ya está finalizado y no se puede modificar.",
  ServiceNotFinalized: "La reclamación requiere un mantenimiento finalizado.",
  InvalidRecordId: "El identificador de mantenimiento no corresponde a la secuencia.",
  InvalidClaimId: "El identificador de reclamación no corresponde a la secuencia.",
  ClaimAlreadyOpen: "Este mantenimiento ya tiene una reclamación abierta.",
  ClaimNotOpen: "La reclamación ya está resuelta.",
  ClaimWindowExpired: "El periodo de garantía (90 días) ha terminado.",
  OpenClaimsExist: "No se puede archivar: existen reclamaciones abiertas.",
  PendingServicesExist: "No se puede archivar: existen mantenimientos pendientes.",
  AlreadyArchived: "La motocicleta ya está archivada.",
  AccountMismatch: "Las cuentas enviadas no pertenecen a la misma relación.",
  InvalidState: "El taller ya se encuentra en el estado solicitado.",
  ArithmeticOverflow: "Desbordamiento numérico al actualizar un contador.",
};

/** Translate an Anchor program error into a human-readable message. */
export function explainError(err: unknown): string {
  const e = err as any;
  const code: string | undefined =
    e?.error?.errorCode?.code ??
    (typeof e?.message === "string"
      ? (e.message.match(/custom program error: 0x[0-9a-f]+/i)?.[0] as string | undefined)
      : undefined);
  if (code && ERROR_MESSAGES[code]) return ERROR_MESSAGES[code];
  if (typeof e?.message === "string") return e.message.split("\n")[0];
  return "Error desconocido al procesar la transacción";
}

export type MutateResult = { signature: string; address?: PublicKey };

export class MotoraClient {
  readonly program: Program;
  readonly programId: PublicKey;

  constructor(provider: Provider, programId: PublicKey) {
    this.programId = programId;
    // Anchor 0.32 reads the program address from the IDL, so override it with
    // the explicit programId to keep the client and the deployed ID in sync.
    this.program = new Program(
      { ...IDL, address: programId.toBase58() } as Idl,
      provider,
    );
  }

  static fromProvider(provider: Provider, programId: PublicKey) {
    return new MotoraClient(provider, programId);
  }

  static fromConnection(connection: Connection, wallet: Wallet, programId: PublicKey) {
    return new MotoraClient(new AnchorProvider(connection, wallet, {}), programId);
  }

  // ---- reads -------------------------------------------------------------

  /** Account namespace is cast because the IDL is loaded as generic `Idl`. */
  private get accounts(): any {
    return (this.program as any).account;
  }

  protocol() {
    const [protocol] = PublicKey.findProgramAddressSync([enc("protocol")], this.programId);
    return this.accounts.protocol.fetch(protocol);
  }

  motorcycles(owner?: PublicKey) {
    return this.accounts.motorcycle.all().then((rows: any[]) =>
      owner ? rows.filter((r) => r.account.owner.equals(owner)) : rows,
    );
  }

  workshops(authority?: PublicKey) {
    return this.accounts.workshop.all().then((rows: any[]) =>
      authority ? rows.filter((r) => r.account.authority.equals(authority)) : rows,
    );
  }

  serviceRecords(motorcycle?: PublicKey) {
    return this.accounts.serviceRecord.all().then((rows: any[]) =>
      motorcycle ? rows.filter((r) => r.account.motorcycle.equals(motorcycle)) : rows,
    );
  }

  claims(claimant?: PublicKey) {
    return this.accounts.warrantyClaim.all().then((rows: any[]) =>
      claimant ? rows.filter((r) => r.account.claimant.equals(claimant)) : rows,
    );
  }

  motorcycle(address: PublicKey) {
    return this.accounts.motorcycle.fetch(address);
  }

  workshop(address: PublicKey) {
    return this.accounts.workshop.fetch(address);
  }

  serviceRecord(address: PublicKey) {
    return this.accounts.serviceRecord.fetch(address);
  }

  claim(address: PublicKey) {
    return this.accounts.warrantyClaim.fetch(address);
  }

  // ---- writes ------------------------------------------------------------

  async initialize(): Promise<MutateResult> {
    const { protocol } = derivePdas(this.programId, new Uint8Array(32));
    const signature = await this.program.methods
      .initialize()
      .accounts({ protocol })
      .rpc();
    return { signature, address: protocol };
  }

  async registerMotorcycle(args: {
    owner: PublicKey;
    identifierHash: Uint8Array;
    brand: string;
    model: string;
    year: number;
    initialMileage: number;
  }): Promise<MutateResult> {
    const { protocol, motorcycle } = derivePdas(this.programId, args.identifierHash);
    const signature = await this.program.methods
      .registerMotorcycle(
        Array.from(args.identifierHash),
        args.brand,
        args.model,
        args.year,
        new BN(args.initialMileage),
      )
      .accounts({ protocol, motorcycle, owner: args.owner, systemProgram: SystemProgram.programId })
      .rpc();
    return { signature, address: motorcycle };
  }

  async updateMotorcycle(args: {
    owner: PublicKey;
    identifierHash: Uint8Array;
    brand: string;
    model: string;
    mileage: number;
  }): Promise<MutateResult> {
    const { motorcycle } = derivePdas(this.programId, args.identifierHash);
    const signature = await this.program.methods
      .updateMotorcycle(args.brand, args.model, new BN(args.mileage))
      .accounts({ motorcycle, owner: args.owner })
      .rpc();
    return { signature, address: motorcycle };
  }

  async registerWorkshop(args: { authority: PublicKey; name: string }): Promise<MutateResult> {
    const [protocol] = PublicKey.findProgramAddressSync([enc("protocol")], this.programId);
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const signature = await this.program.methods
      .registerWorkshop(args.name)
      .accounts({ protocol, workshop, authority: args.authority, systemProgram: SystemProgram.programId })
      .rpc();
    return { signature, address: workshop };
  }

  async setWorkshopStatus(args: {
    authority: PublicKey;
    active: boolean;
  }): Promise<MutateResult> {
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const signature = await this.program.methods
      .setWorkshopStatus(args.active)
      .accounts({ workshop, authority: args.authority })
      .rpc();
    return { signature, address: workshop };
  }

  async createServiceRecord(args: {
    authority: PublicKey;
    identifierHash: Uint8Array;
    motorcycle: PublicKey | string;
    recordId: number;
    mileage: number;
    serviceType: string;
    description: string;
  }): Promise<MutateResult> {
    const motorcycle = asPublicKey(args.motorcycle);
    const [protocol] = PublicKey.findProgramAddressSync([enc("protocol")], this.programId);
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const [serviceRecord] = deriveServicePda(this.programId, motorcycle, args.recordId);
    const signature = await this.program.methods
      .createServiceRecord(
        new BN(args.recordId),
        new BN(args.mileage),
        args.serviceType,
        args.description,
      )
      .accounts({
        protocol,
        motorcycle,
        workshop,
        serviceRecord,
        authority: args.authority,
        systemProgram: SystemProgram.programId,
      })
      .rpc();
    return { signature, address: serviceRecord };
  }

  async updateServiceRecord(args: {
    authority: PublicKey;
    motorcycle: PublicKey | string;
    serviceRecord: PublicKey | string;
    mileage: number;
    serviceType: string;
    description: string;
  }): Promise<MutateResult> {
    const motorcycle = asPublicKey(args.motorcycle);
    const serviceRecord = asPublicKey(args.serviceRecord);
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const signature = await this.program.methods
      .updateServiceRecord(new BN(args.mileage), args.serviceType, args.description)
      .accounts({
        motorcycle,
        workshop,
        serviceRecord,
        authority: args.authority,
      })
      .rpc();
    return { signature, address: serviceRecord };
  }

  async finalizeServiceRecord(args: {
    authority: PublicKey;
    motorcycle: PublicKey | string;
    serviceRecord: PublicKey | string;
  }): Promise<MutateResult> {
    const motorcycle = asPublicKey(args.motorcycle);
    const serviceRecord = asPublicKey(args.serviceRecord);
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const signature = await this.program.methods
      .finalizeServiceRecord()
      .accounts({
        motorcycle,
        workshop,
        serviceRecord,
        authority: args.authority,
      })
      .rpc();
    return { signature, address: serviceRecord };
  }

  async createWarrantyClaim(args: {
    claimant: PublicKey;
    motorcycle: PublicKey | string;
    serviceRecord: PublicKey | string;
    claimId: number;
    description: string;
  }): Promise<MutateResult> {
    const motorcycle = asPublicKey(args.motorcycle);
    const serviceRecord = asPublicKey(args.serviceRecord);
    const [protocol] = PublicKey.findProgramAddressSync([enc("protocol")], this.programId);
    const [warrantyClaim] = deriveClaimPda(this.programId, serviceRecord, args.claimId);
    const signature = await this.program.methods
      .createWarrantyClaim(new BN(args.claimId), args.description)
      .accounts({
        protocol,
        motorcycle,
        serviceRecord,
        warrantyClaim,
        claimant: args.claimant,
        systemProgram: SystemProgram.programId,
      })
      .rpc();
    return { signature, address: warrantyClaim };
  }

  async resolveWarrantyClaim(args: {
    authority: PublicKey;
    motorcycle: PublicKey | string;
    serviceRecord: PublicKey | string;
    warrantyClaim: PublicKey | string;
    resolution: string;
  }): Promise<MutateResult> {
    const motorcycle = asPublicKey(args.motorcycle);
    const serviceRecord = asPublicKey(args.serviceRecord);
    const warrantyClaim = asPublicKey(args.warrantyClaim);
    const [workshop] = deriveWorkshopPda(this.programId, args.authority);
    const signature = await this.program.methods
      .resolveWarrantyClaim(args.resolution)
      .accounts({
        warrantyClaim,
        serviceRecord,
        motorcycle,
        workshop,
        authority: args.authority,
      })
      .rpc();
    return { signature, address: warrantyClaim };
  }

  async archiveMotorcycle(args: {
    owner: PublicKey;
    identifierHash: Uint8Array;
  }): Promise<MutateResult> {
    const { protocol, motorcycle } = derivePdas(this.programId, args.identifierHash);
    const signature = await this.program.methods
      .archiveMotorcycle(Array.from(args.identifierHash))
      .accounts({ protocol, motorcycle, owner: args.owner })
      .rpc();
    return { signature, address: motorcycle };
  }
}

export default MotoraClient;
